class MemoriaDeslizante:
    def __init__(self, max_turnos=4):
        self.historial = []
        self.max_turnos = max_turnos

    def agregar(self, rol, contenido):
        self.historial.append({"role": rol, "content": contenido})
        if len(self.historial) > self.max_turnos:
            self.historial.pop(0)  # Descarta el mensaje más antiguo

mem = MemoriaDeslizante(max_turnos=2)
mem.agregar("user", "Hola")
mem.agregar("assistant", "¡Hola!")
mem.agregar("user", "¿Cómo estás?")
print("Mensajes conservados:", len(mem.historial))
